        "Embriyonik kökeni aynı olan, yapı ve gelişimleri birbirine benzeyen, aynı veya farklı fonksiyonları yerine getiren organlara homolog organlar denir.",
        "Homolog organlar, görev bakımından farklı olmalarına rağmen organlarının yapısında yer alan kemikler açısından benzer anatomik yapıya ve fizyolojik özelliklere sahiptir."
