        "İnce bağırsaktan salgılanan sindirim enzimleri ise disakkaridazlar (maltaz, laktaz, sukraz), aminopeptidaz, karboksipeptidaz, dipeptidazlar, nükleotidazlar, nükleozidazlar, fosfatazlardır.",
